def countUniformSubstrings(s, k):
    n = len(s)
    codes = [ord(ch) - 97 for ch in s]
    ans = 0
    for d in range(1, min(26, n // k) + 1):
        size = d * k
        cnt = [0] * 26
        eq = 0
        for i in range(n):
            c = codes[i]
            cnt[c] += 1
            if cnt[c] == k:
                eq += 1
            elif cnt[c] == k + 1:
                eq -= 1
            if i >= size:
                c = codes[i - size]
                if cnt[c] == k:
                    eq -= 1
                elif cnt[c] == k + 1:
                    eq += 1
                cnt[c] -= 1
            if i >= size - 1 and eq == d:
                ans += 1
    return ans
